use clap::Parser;
use std::io::{BufWriter, Write};
use std::path::Path;
use std::path::PathBuf;
use std::sync::{Arc, Condvar, Mutex};
use std::thread;
use std::{fs, vec};

// Decoration and Color imports
use indicatif::{ProgressBar, ProgressStyle};
use owo_colors::OwoColorize;
use std::io::IsTerminal;
use std::time::Duration;

#[cfg(target_os = "linux")]
const DEFAULT_EXCLUDES: &[&str] = &[
    "/proc", // one folder per running process, generated by the kernel
    "/sys",  // kernel and hardware info, also generated on the fly
    "/dev",  // device files (disks, terminals), not documents
    "/run",  // runtime data like sockets and PID files, wiped on every boot
];

#[cfg(target_os = "linux")]
const DEFAULT_PATH: &str = "/";

#[cfg(target_os = "macos")]
const DEFAULT_EXCLUDES: &[&str] = &[
    "/dev",
    "/System/Volumes", // mirrors your data volume, so every file would show up twice
    "/Volumes",        // other mounted drives and network shares
    "/private/var/vm", // swap and sleep-image files
];

#[cfg(target_os = "macos")]
const DEFAULT_PATH: &str = "/";

#[cfg(windows)]
const DEFAULT_EXCLUDES: &[&str] = &[
    r"C:\$Recycle.Bin",
    r"C:\System Volume Information", // restore points; always access-denied anyway
    r"C:\Windows\WinSxS",            // component store: tens of thousands of folders
];

#[cfg(windows)]
const DEFAULT_PATH: &str = "C:\\";

#[cfg(not(any(target_os = "linux", target_os = "macos", windows)))]
const DEFAULT_EXCLUDES: &[&str] = &[];

#[cfg(not(any(target_os = "linux", target_os = "macos", windows)))]
const DEFAULT_PATH: &str = "/";

#[derive(Parser)]
#[command(version)]
struct Cli {
    /// Text to look for in file and folder names
    target: String,

    /// Folder to start searching from
    #[arg(default_value = DEFAULT_PATH)]
    path: PathBuf,

    /// Also search folders that are skipped by default, like /proc and /sys
    #[arg(long)]
    bypass_defaults: bool,
}

struct State {
    todo: Vec<PathBuf>,
    busy: usize,
}

fn is_excluded(path: &Path) -> bool {
    DEFAULT_EXCLUDES.iter().any(|x| path == Path::new(x))
}

fn main() {
    let args = Cli::parse();

    let state = Arc::new((
        Mutex::new(State {
            todo: vec![args.path],
            busy: 0,
        }),
        Condvar::new(),
    ));
    let target = Arc::new(args.target);
    let mut handles = Vec::new();

    let n = std::thread::available_parallelism()
        .map(|n| n.get())
        .unwrap_or(4);

    let bypass = args.bypass_defaults;

    let pb = ProgressBar::new_spinner();
    pb.set_style(ProgressStyle::with_template("{spinner:.cyan} {msg} | {pos} folders").unwrap());
    pb.enable_steady_tick(Duration::from_millis(80));
    pb.set_message("Searching your files");

    let color = std::io::stdout().is_terminal();

    for _ in 0..n {
        let state = Arc::clone(&state);
        let target = Arc::clone(&target);
        let pb = pb.clone();

        handles.push(thread::spawn(move || {
            loop {
                let (lock, cvar) = &*state;
                pb.inc(1);
                let dir = {
                    let mut state = lock.lock().unwrap();

                    if let Some(dir) = state.todo.pop() {
                        state.busy += 1;
                        dir
                    } else if state.busy == 0 {
                        break;
                    } else {
                        drop(cvar.wait(state).unwrap());
                        continue;
                    }
                };

                let mut private_bucket: Vec<PathBuf> = vec![];
                let mut matches: Vec<String> = vec![];

                if let Ok(entries) = fs::read_dir(&dir) {
                    entries.for_each(|r| {
                        let Ok(entry) = r else { return };
                        let path: PathBuf = entry.path();

                        if entry
                            .file_name()
                            .to_string_lossy()
                            .contains(target.as_str())
                        {
                            matches.push(entry.file_name().to_string_lossy().into_owned());
                        }

                        if let Ok(file_type) = entry.file_type()
                            && file_type.is_dir()
                            && (bypass || !is_excluded(&path))
                        {
                            private_bucket.push(path.clone());
                        }
                    });
                }

                if !matches.is_empty() {
                    pb.suspend(|| {
                        let mut out = BufWriter::new(std::io::stdout().lock());

                        for m in matches {
                            let full = dir.join(&m).display().to_string();
                            let split = full.len() - m.len(); // where the name starts
                            let (folder, name) = (&full[..split], &full[split..]);

                            if color {
                                let _ = writeln!(out, "{}{}", folder.dimmed(), name.green().bold());
                            } else {
                                let _ = writeln!(out, "{}", full);
                            }
                        }
                    });
                }

                let mut guard = lock.lock().unwrap();

                let added = private_bucket.len();
                guard.todo.append(&mut private_bucket);
                guard.busy -= 1;

                for _ in 0..added {
                    cvar.notify_one();
                }

                if guard.busy == 0 {
                    cvar.notify_all();
                }
            }
        }));
    }

    for h in handles {
        h.join().unwrap()
    }

    pb.finish_and_clear();
}
